import assert from 'node:assert/strict';
import {archiveServiceFixture} from './helpers/private-gallery-service-fixture.mjs';
import {handleAdminRequest} from '../gallery-admin/src/admin-worker.js';
import {createBrowserSession} from '../gallery-admin/src/session.js';

// Actual owner router and migrated SQLite, invented people and generated bytes
// only. The browser may reserve a job; it cannot dispatch, process or publish.
const origin='https://synthetic-batch-owner.example';
for(const site of ['family','everyone']) {
    const f=await archiveServiceFixture(site);
    f.env.DB.batch=async statements=>{f.db.exec('BEGIN');try{const results=[];for(const statement of statements)results.push(await statement.run());f.db.exec('COMMIT');return results;}catch(error){f.db.exec('ROLLBACK');throw error;}};
    const env={DB:f.env.DB,PRIVATE_ORIGINALS:f.original,ADMIN_ORIGIN:origin,
        OWNER_IDENTITIES:`subject:${f.owner.subject}`,SESSION_SECRET:'synthetic-batch-owner-session-secret'};
    const session=await createBrowserSession(f.owner,env,site,Date.now());
    const opposite=await createBrowserSession(f.owner,env,site==='family'?'everyone':'family',Date.now());
    const headers={Cookie:session.cookie.split(';')[0],'X-CSRF-Token':session.csrfToken,
        Origin:origin,'Sec-Fetch-Site':'same-origin'};
    const dependencies={verifyAccessIdentity:async()=>f.owner,bodyTimeoutMilliseconds:15};
    const path='/api/browser/private-batches';
    const request=(body,extra={},query=`?site=${site}`)=>new Request(origin+path+query,{
        method:body===undefined?'GET':'POST',headers:{...headers,...(body===undefined?{}:{'Content-Type':'application/json'}),...extra},
        body:body===undefined?undefined:JSON.stringify(body)});
    const run=(req,deps=dependencies)=>handleAdminRequest(req,env,deps);
    const body={attemptIds:[f.attemptId],idempotencyKey:crypto.randomUUID()};
    const retained=()=>JSON.stringify({assets:f.db.prepare('SELECT * FROM private_gallery_assets').all(),
        tags:f.db.prepare('SELECT * FROM private_gallery_asset_tags').all(),attempts:f.db.prepare('SELECT * FROM private_gallery_attempts').all(),
        originals:f.db.prepare('SELECT * FROM private_archive_original_receipts').all()});
    const before=retained(),calls=f.original.calls.length;
    for(const [extra,identity] of [
        [{Cookie:''},f.owner],[{'X-CSRF-Token':'wrong'},f.owner],[{Origin:'https://untrusted.example'},f.owner],
        [{'Sec-Fetch-Site':'cross-site'},f.owner],[{Cookie:opposite.cookie.split(';')[0],'X-CSRF-Token':opposite.csrfToken},f.owner],
        [{'Cf-Access-Client-Id':'not-a-browser'},f.owner],[{},null],[{},{type:'service',subject:f.owner.subject}],
        [{},{type:'browser',subject:'different-fictional-owner'}]
    ]) assert.equal((await run(request(body,extra),{...dependencies,verifyAccessIdentity:async()=>identity})).status,403);
    for(const query of ['', '?site=invalid',`?site=${site}&site=${site}`,`?site=${site}&target=everyone`])
        assert.equal((await run(request(body,{},query))).status,404);
    assert.equal((await run(request(undefined,{'Content-Type':'application/json'}))).status,400);
    assert.equal((await run(request(body,{'Content-Encoding':'gzip'}))).status,400);
    assert.equal((await run(request(body,{'Transfer-Encoding':'chunked'}))).status,400);
    assert.equal((await run(request(body,{'Content-Length':'999999'}))).status,413);
    for(const invalid of [{...body,siteMode:site},{...body,ownerHash:'invented'},
        {...body,attemptIds:[]},{...body,attemptIds:[f.attemptId,f.attemptId]},
        {...body,attemptIds:Array.from({length:21},()=>`attempt_${crypto.randomUUID()}`)},
        {...body,attemptIds:['not-an-attempt']},{...body,idempotencyKey:'not-a-key'}])
        assert.equal((await run(request(invalid))).status,422);
    const wrongArea=site==='family'?'everyone':'family';
    assert.equal((await run(request(body,{Cookie:opposite.cookie.split(';')[0],'X-CSRF-Token':opposite.csrfToken},`?site=${wrongArea}`))).status,409);
    const utf8=new Request(origin+path+`?site=${site}`,{method:'POST',headers:{...headers,'Content-Type':'application/json'},body:new Uint8Array([255,254])});
    assert.equal((await run(utf8)).status,400);
    const stalled=new Request(origin+path+`?site=${site}`,{method:'POST',duplex:'half',headers:{...headers,'Content-Type':'application/json'},
        body:new ReadableStream({start(controller){controller.enqueue(new TextEncoder().encode('{'));},cancel(){return new Promise(()=>{});}})});
    const started=Date.now();assert.equal((await run(stalled)).status,400);assert.ok(Date.now()-started<1500);
    const empty=await run(request());assert.equal(empty.status,200);assert.deepEqual((await empty.json()).batches,[]);
    const saved=await run(request(body));assert.equal(saved.status,201,await saved.clone().text());
    const result=await saved.json();assert.equal(result.publicationEnabled,false);assert.match(result.job.jobId,/^job_/);
    const replay=await run(request(body));assert.equal(replay.status,200);assert.equal((await replay.json()).job.jobId,result.job.jobId);
    const jobs=await (await run(request())).json();assert.equal(jobs.batches.length,1);
    assert.deepEqual(jobs.batches[0].attemptIds,[f.attemptId]);assert.equal(jobs.batches[0].state,'queued');
    assert.equal(retained(),before,'Batch selection cannot rewrite photo, tags, consent or original evidence');
    assert.equal(f.original.calls.length,calls,'Owner batch routes have no original-byte I/O');
    assert.equal(f.db.prepare('SELECT count(*) n FROM private_gallery_pipeline_admissions').get().n,0);
    assert.equal(f.db.prepare('SELECT count(*) n FROM private_gallery_job_claims').get().n,0,'The owner browser never starts or claims a protected job');
    const shell=await run(new Request(`${origin}/private-gallery?site=${site}`,{headers}));
    assert.equal(shell.status,200);assert.equal(shell.headers.get('Cache-Control'),'no-store');
    const html=await shell.text();assert.match(html,/Request combined review job/);assert.match(html,/Each photo keeps its own consent and safety checks/);
    assert.doesNotMatch(html,/<select[^>]+(?:name|id)="(?:site|destination)"/);
    f.db.close();
}
console.log('Protected batch owner route passed in both areas: owner/session/CSRF/origin/body limits, exact saved attempts, idempotent jobs and zero media/processing/publication I/O.');
